customMethods.script:
result = BlueRidge.Sim.fireScale(self.view.custom.selectedDevice, self.view.custom.inNetWeight, self.view.custom.inMetFlag)
if not result["ok"]:
	BlueRidge.Common.Notify.toast("Write failed", result["message"], "error")

result = BlueRidge.Sim.setScaleTarget(self.view.custom.selectedDevice, self.view.custom.inTargetWeight)
if not result["ok"]:
	BlueRidge.Common.Notify.toast("Write failed", result["message"], "error")

result = BlueRidge.Sim.fireSerialized(self.view.custom.selectedDevice, self.view.custom.inPartSN, self.view.custom.inInterlock)
if not result["ok"]:
	BlueRidge.Common.Notify.toast("Write failed", result["message"], "error")

result = BlueRidge.Sim.pulse(self.view.custom.selectedDevice, "PartComplete")
if not result["ok"]:
	BlueRidge.Common.Notify.toast("Write failed", result["message"], "error")

result = BlueRidge.Sim.pulse(self.view.custom.selectedDevice, "ContainerCountRequest")
if not result["ok"]:
	BlueRidge.Common.Notify.toast("Write failed", result["message"], "error")

result = BlueRidge.Sim.pulse(self.view.custom.selectedDevice, "DataReady")
if not result["ok"]:
	BlueRidge.Common.Notify.toast("Write failed", result["message"], "error")

result = BlueRidge.Sim.pulse(self.view.custom.selectedDevice, "TrayLocked")
if not result["ok"]:
	BlueRidge.Common.Notify.toast("Write failed", result["message"], "error")

messageHandlers.script:
p = payload or {}
idx = p.get("index")
if idx is None:
	return
pending = BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.pendingScenarios) or []
self.view.custom.pendingScenarios = [s for s in pending if s.get("index") != idx]
if p.get("outcome") == "failed":
	failed = BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.failedScenarios) or []
	failed.append({"title": p.get("title", ""), "note": ""})
	self.view.custom.failedScenarios = failed
